# Calibration, ANRI, DPP, expected utility, Bayesian curves and RAC.
# Each sub-tab has its own reactive, so only the visible one is computed.

calibration_ui <- function(id) {
  ns <- NS(id)
  bslib::layout_sidebar(
    sidebar = bslib::sidebar(
      width = 320,
      uiOutput(ns("banner")),
      checkboxInput(ns("choosers"), "Choosers only (suspect and filler IDs)", value = TRUE),
      bslib::layout_columns(
        numericInput(ns("n_boot"), "ANRI and DPP bootstrap R", value = 1000, min = 100, step = 100),
        numericInput(ns("seed"), "Seed", value = 2026, step = 1)
      ),
      tags$strong("Expected utility"),
      sliderInput(ns("base_rate"), "Base rate of guilt", min = 0.05, max = 0.95, value = 0.5, step = 0.05),
      bslib::layout_columns(
        col_widths = c(6, 6),
        numericInput(ns("u_tp"), "Utility: guilty ID", value = 1, step = 0.5),
        numericInput(ns("u_fn"), "Utility: guilty missed", value = -0.5, step = 0.5),
        numericInput(ns("u_fp"), "Utility: innocent ID", value = -2, step = 0.5),
        numericInput(ns("u_tn"), "Utility: innocent cleared", value = 0.5, step = 0.5)
      ),
      selectInput(ns("bayes_cat"), "Bayesian curves: response categories",
                  choices = c("By confidence" = "confidence", "Suspect / filler / reject" = "simple")),
      textInput(ns("time_bins"), "RAC response-time bin edges (blank = quintiles)", value = ""),
      run_button(ns("run"))
    ),
    bslib::navset_card_underline(
      id = ns("tabs"),
      bslib::nav_panel(
        "Calibration",
        uiOutput(ns("cal_notes")),
        uiOutput(ns("scope")),
        bslib::layout_column_wrap(
          width = 1 / 3, fill = FALSE,
          bslib::value_box("Calibration C", textOutput(ns("vb_c")), theme = "primary"),
          bslib::value_box("Over/underconfidence", textOutput(ns("vb_ou")), theme = "light"),
          bslib::value_box("Resolution NRI", textOutput(ns("vb_nri")), theme = "light")
        ),
        plot_card(ns, "cal_plot", "Calibration curve", height = "460px"),
        table_card(ns, "cal_table", "Calibration by confidence bin")
      ),
      bslib::nav_panel(
        "ANRI",
        uiOutput(ns("anri_notes")),
        table_card(ns, "anri_table", "Adjusted normalised resolution index"),
        plot_card(ns, "anri_plot", "ANRI comparison")
      ),
      bslib::nav_panel(
        "DPP",
        uiOutput(ns("dpp_notes")),
        table_card(ns, "dpp_table", "Deviation from perfect performance"),
        plot_card(ns, "dpp_plot", "DPP by operating point")
      ),
      bslib::nav_panel(
        "Expected utility",
        uiOutput(ns("util_notes")),
        bslib::layout_columns(
          col_widths = c(6, 6),
          plot_card(ns, "util_plot", "Expected utility by decision criterion"),
          table_card(ns, "util_table", "Utility by criterion")
        )
      ),
      bslib::nav_panel(
        "Bayesian curves",
        uiOutput(ns("bayes_notes")),
        plot_card(ns, "bayes_pp", "Prior-posterior curves", height = "460px"),
        plot_card(ns, "bayes_ig", "Information gain", height = "460px"),
        plot_card(ns, "bree_plot", "Base-rate effect equivalency (two groups)")
      ),
      bslib::nav_panel(
        "RAC",
        uiOutput(ns("rac_notes")),
        bslib::layout_columns(
          col_widths = c(6, 6),
          plot_card(ns, "rac_plot", "Response time-accuracy characteristic"),
          table_card(ns, "rac_table", "Accuracy by response-time bin")
        )
      )
    )
  )
}

calibration_server <- function(id, data) {
  moduleServer(id, function(input, output, session) {
    output$banner <- renderUI(data_banner(data()))

    # Wraps one analysis so that it reruns on Run or on new data.
    analysis <- function(fn) {
      reactive({
        capture_notes(fn(data()))
      }) |>
        bindEvent(input$run, data(), ignoreNULL = FALSE)
    }

    cal <- analysis(function(d) {
      single <- r4lineups::make_calibration(d$data, d$bins, choosers_only = isTRUE(input$choosers),
                                            lineup_size = d$lineup_size,
                                            innocent_suspect = d$innocent_suspect, show_plot = FALSE)
      by_group <- if (!is.null(d$groups)) {
        df <- rbind(d$groups$data[[1]], d$groups$data[[2]])
        r4lineups::make_calibration_by_condition(df, d$groups$column, d$bins,
                                                 choosers_only = isTRUE(input$choosers),
                                                 lineup_size = d$lineup_size,
                                                 innocent_suspect = d$innocent_suspect)
      }
      list(single = single, by_group = by_group)
    })
    output$cal_notes <- renderUI(notes_ui(cal()$notes))
    output$scope <- renderUI(group_scope_note(data(), "The summary boxes use all rows; the plot and table compare the groups."))
    output$vb_c <- renderText(fmt_num(cal()$value$single$C, 4))
    output$vb_ou <- renderText(fmt_num(cal()$value$single$OU))
    output$vb_nri <- renderText(fmt_num(cal()$value$single$NRI))
    serve_plot(output, "cal_plot", function() {
      v <- cal()$value
      if (is.null(v$by_group)) r4lineups::make_calibration_gg(v$single)
      else r4lineups::make_calibration_by_condition_gg(v$by_group)
    }, "calibration.png")
    serve_table(output, "cal_table", function() {
      v <- cal()$value
      if (is.null(v$by_group)) v$single$calibration_data else v$by_group$condition_summary
    }, "calibration.csv")

    anri <- analysis(function(d) {
      common <- list(confidence_bins = d$bins, choosers_only = isTRUE(input$choosers),
                     lineup_size = d$lineup_size,
                     innocent_suspect = d$innocent_suspect, n_bootstrap = as.integer(input$n_boot),
                     seed = input$seed)
      if (is.null(d$groups)) {
        list(single = do.call(r4lineups::bootstrap_anri, c(list(data = d$data), common)))
      } else {
        df <- rbind(d$groups$data[[1]], d$groups$data[[2]])
        df[[d$groups$column]] <- factor(df[[d$groups$column]], levels = d$groups$labels)
        list(compare = do.call(r4lineups::compare_anri,
                               c(list(data = df, group_var = d$groups$column), common)))
      }
    })
    output$anri_notes <- renderUI(notes_ui(anri()$notes))
    serve_table(output, "anri_table", function() {
      v <- anri()$value
      if (!is.null(v$single)) {
        s <- v$single
        return(data.frame(quantity = c("ANRI", "NRI", sprintf("%d%% CI (ANRI)", round(100 * s$conf_level)),
                                       "N", "Bins", "Bootstrap R"),
                          value = c(fmt_num(s$anri, 4), fmt_num(s$nri, 4), fmt_ci(c(s$ci_lower, s$ci_upper), 4),
                                    s$n_total, s$n_bins, s$n_bootstrap)))
      }
      cmp <- v$compare
      data.frame(
        quantity = c(paste("ANRI", cmp$group_names), "Difference",
                     sprintf("%d%% CI of difference", round(100 * cmp$conf_level)), "Significant"),
        value = c(fmt_num(cmp$anri_group1, 4), fmt_num(cmp$anri_group2, 4), fmt_num(cmp$difference, 4),
                  fmt_ci(c(cmp$ci_lower, cmp$ci_upper), 4), cmp$significant)
      )
    }, "anri.csv")
    serve_plot(output, "anri_plot", function() {
      v <- anri()$value
      validate(need(!is.null(v$compare), "Choose two groups on the Data tab to compare ANRI."))
      r4lineups::plot_anri_comparison(v$compare)
    }, "anri_comparison.png")

    dpp <- analysis(function(d) {
      if (is.null(d$groups)) {
        list(single = r4lineups::make_dpp(d$data, lineup_size = d$lineup_size,
                                          innocent_suspect = d$innocent_suspect))
      } else {
        list(compare = r4lineups::compare_dpp(d$groups$data[[1]], d$groups$data[[2]],
                                              lineup_size = d$lineup_size,
                                              innocent_suspect = d$innocent_suspect,
                                              n_bootstrap = as.integer(input$n_boot),
                                              seed = input$seed))
      }
    })
    output$dpp_notes <- renderUI(notes_ui(dpp()$notes))
    serve_table(output, "dpp_table", function() {
      v <- dpp()$value
      d <- data()
      if (!is.null(v$single)) {
        s <- v$single
        pts <- s$dpp_by_point
        return(data.frame(
          quantity = c("Average DPP", paste("DPP at confidence >=", pts$confidence)),
          value = c(fmt_num(s$dpp), vapply(pts$dpp, fmt_num, character(1)))
        ))
      }
      cmp <- v$compare
      data.frame(quantity = c(paste("Average DPP", d$groups$labels), "Difference",
                              "Bootstrap SE", sprintf("%g%% CI", 100 * cmp$conf_level)),
                 value = c(fmt_num(cmp$dpp_a), fmt_num(cmp$dpp_b),
                           fmt_num(cmp$dpp_difference), fmt_num(cmp$se_difference),
                           sprintf("[%s, %s]", fmt_num(cmp$ci_difference[["lower"]]),
                                   fmt_num(cmp$ci_difference[["upper"]]))))
    }, "dpp.csv")
    serve_plot(output, "dpp_plot", function() {
      v <- dpp()$value
      if (!is.null(v$single)) return(r4lineups::plot_dpp(v$single))
      lab <- data()$groups$labels
      r4lineups::plot_dpp_comparison(v$compare, proc_a_label = lab[1], proc_b_label = lab[2])
    }, "dpp.png")

    util <- analysis(function(d) {
      um <- c(tp = input$u_tp, fn = input$u_fn, fp = input$u_fp, tn = input$u_tn)
      r4lineups::make_utility_curves(d$data, base_rate = input$base_rate, utility_matrix = um,
                                     lineup_size = d$lineup_size,
                                     innocent_suspect = d$innocent_suspect)
    })
    output$util_notes <- renderUI(notes_ui(util()$notes))
    serve_plot(output, "util_plot", function() r4lineups::plot_utility_curves(util()$value),
               "utility.png")
    serve_table(output, "util_table", function() util()$value$utility_data, "utility.csv")

    bayes <- analysis(function(d) {
      r4lineups::make_bayes_curves(d$data, response_categories = input$bayes_cat,
                                   confidence_bins = d$bins, lineup_size = d$lineup_size,
                                   innocent_suspect = d$innocent_suspect)
    })
    output$bayes_notes <- renderUI(notes_ui(bayes()$notes))
    serve_plot(output, "bayes_pp", function() r4lineups::plot_bayes_prior_posterior(bayes()$value),
               "bayes_prior_posterior.png")
    serve_plot(output, "bayes_ig", function() r4lineups::plot_bayes_information_gain(bayes()$value),
               "bayes_information_gain.png")

    # BREE compares suspect identifications regardless of confidence.
    bree <- analysis(function(d) {
      validate(need(!is.null(d$groups), "Choose two groups on the Data tab for the BREE curve."))
      r4lineups::make_bree_curve(d$groups$data[[1]], d$groups$data[[2]],
                                 lineup_size = d$lineup_size,
                                 innocent_suspect = d$innocent_suspect)
    })
    serve_plot(output, "bree_plot", function() r4lineups::plot_bree(bree()$value), "bree.png")

    rac <- analysis(function(d) {
      validate(need(d$has_rt, "RAC needs a response_time column in the data."))
      bins <- parse_bins(input$time_bins)
      if (is.null(bins)) {
        rt <- d$data$response_time[d$data$identification == "suspect"]
        bins <- unique(stats::quantile(rt, seq(0, 1, 0.2), na.rm = TRUE, names = FALSE))
      }
      r4lineups::make_racdata(d$data, lineup_size = d$lineup_size,
                              innocent_suspect = d$innocent_suspect, time_bins = bins)
    })
    output$rac_notes <- renderUI(notes_ui(rac()$notes))
    serve_plot(output, "rac_plot", function() r4lineups::make_rac_gg(rac()$value), "rac.png")
    serve_table(output, "rac_table", function() rac()$value$rac_data, "rac.csv")

    list(cal = cal, anri = anri, dpp = dpp, util = util, bayes = bayes, bree = bree, rac = rac)
  })
}

# Data tab: one confidence-based data set shared by the ROC, calibration,
# EIG/PPV, Multi-d' and Bayesian calibration analyses.

data_required_cols <- c("target_present", "identification", "confidence")

data_ui <- function(id) {
  ns <- NS(id)
  bslib::layout_sidebar(
    sidebar = bslib::sidebar(
      width = 320,
      radioButtons(
        ns("source"), "Data source",
        choices = c(
          "Built-in: lineup_example" = "lineup_example",
          "Built-in: two simulated procedures" = "two_procedures",
          "Upload CSV" = "upload"
        )
      ),
      conditionalPanel(
        sprintf("input['%s'] == 'upload'", ns("source")),
        fileInput(ns("file"), NULL, accept = ".csv"),
        downloadLink(ns("template"), "Download a template CSV")
      ),
      numericInput(ns("lineup_size"), "Nominal lineup size", value = 6, min = 2, step = 1),
      selectInput(ns("innocent_suspect"), "Innocent suspect in target-absent lineups",
                  choices = c("Auto-detect" = "auto",
                              "Designated suspect" = "designated",
                              "None: estimate from fillers" = "estimated")),
      textInput(ns("bins"), "Confidence bins (edges)", value = "0, 60, 80, 100"),
      helpText("Bin edges are used by CAC, full ROC, calibration, EIG and PPV."),
      selectInput(ns("group_col"), "Compare two groups by column", choices = c("None" = "")),
      uiOutput(ns("group_levels_ui"))
    ),
    uiOutput(ns("status")),
    bslib::layout_column_wrap(
      width = 1 / 3, fill = FALSE,
      bslib::value_box("Lineups", textOutput(ns("n_rows")), theme = "primary"),
      bslib::value_box("Target present / absent", textOutput(ns("n_tp_ta")), theme = "light"),
      bslib::value_box("Suspect / filler / reject", textOutput(ns("n_resp")), theme = "light")
    ),
    bslib::card(
      bslib::card_header("Preview"),
      DT::DTOutput(ns("preview"))
    ),
    bslib::card(
      bslib::card_header("Expected format"),
      tags$p(
        "One row per witness. Required columns: ",
        tags$code("target_present"), " (TRUE/FALSE or 1/0), ",
        tags$code("identification"), " (suspect, filler or reject) and ",
        tags$code("confidence"), " (numeric). If ", tags$code("identification"),
        " is missing but ", tags$code("lineup_member"), " (0 = rejection) and ",
        tags$code("suspect_pos"), " are present, it is derived with ",
        tags$code("classify_lineup_choices()"), ". A ", tags$code("response_time"),
        " column enables the RAC analysis, and any other column can be used to compare two groups."
      )
    )
  )
}

data_server <- function(id) {
  moduleServer(id, function(input, output, session) {
    raw <- reactive({
      if (identical(input$source, "upload")) {
        req(input$file)
        utils::read.csv(input$file$datapath, stringsAsFactors = FALSE)
      } else {
        example_trial_data(input$source)
      }
    })

    observeEvent(input$source, {
      size <- if (identical(input$source, "upload")) input$lineup_size else 6
      updateNumericInput(session, "lineup_size", value = size)
      bins <- "0, 60, 80, 100"
      updateTextInput(session, "bins", value = bins)
    })

    prepared <- reactive({
      df <- raw()
      notes <- character()
      if (!"identification" %in% names(df) &&
          all(c("lineup_member", "suspect_pos") %in% names(df))) {
        df <- safely_validate(r4lineups::classify_lineup_choices(df, k = input$lineup_size))
        notes <- c(notes, "identification was derived from lineup_member and suspect_pos.")
      }
      missing <- setdiff(data_required_cols, names(df))
      validate(need(length(missing) == 0,
                    paste("Missing required column(s):", paste(missing, collapse = ", "))))
      tp <- df$target_present
      if (is.character(tp)) tp <- toupper(trimws(tp)) %in% c("TRUE", "T", "1", "TP", "YES")
      df$target_present <- as.logical(tp)
      df$identification <- tolower(trimws(df$identification))
      bad <- setdiff(unique(df$identification), c("suspect", "filler", "reject"))
      validate(need(length(bad) == 0,
                    paste("identification must be suspect, filler or reject; found:",
                          paste(utils::head(bad, 5), collapse = ", "))))
      validate(need(is.numeric(df$confidence), "confidence must be numeric."))
      list(data = df, notes = notes)
    })

    observe({
      df <- raw()
      candidates <- names(df)[vapply(df, function(x) {
        n <- length(unique(x))
        n >= 2 && n <= 20
      }, logical(1))]
      candidates <- setdiff(candidates, c(data_required_cols, "lineup_member", "suspect_pos"))
      selected <- if ("procedure" %in% candidates) "procedure" else ""
      updateSelectInput(session, "group_col", choices = c("None" = "", candidates),
                        selected = selected)
    })

    output$group_levels_ui <- renderUI({
      req(nzchar(input$group_col))
      lv <- sort(unique(raw()[[input$group_col]]))
      tagList(
        selectInput(session$ns("level1"), "Group 1", choices = lv, selected = lv[1]),
        selectInput(session$ns("level2"), "Group 2", choices = lv, selected = lv[min(2, length(lv))])
      )
    })

    groups <- reactive({
      col <- input$group_col
      if (is.null(col) || !nzchar(col) || is.null(input$level1) || is.null(input$level2) ||
          identical(input$level1, input$level2)) {
        return(NULL)
      }
      df <- prepared()$data
      lv <- c(input$level1, input$level2)
      out <- lapply(lv, function(l) df[as.character(df[[col]]) == l, , drop = FALSE])
      if (any(vapply(out, nrow, integer(1)) == 0)) {
        return(NULL)
      }
      names(out) <- lv
      list(column = col, labels = lv, data = out)
    })

    output$status <- renderUI({
      p <- prepared()
      notes_ui(p$notes)
    })

    output$n_rows <- renderText(nrow(prepared()$data))
    output$n_tp_ta <- renderText({
      tp <- prepared()$data$target_present
      sprintf("%d / %d", sum(tp, na.rm = TRUE), sum(!tp, na.rm = TRUE))
    })
    output$n_resp <- renderText({
      tab <- table(factor(prepared()$data$identification, c("suspect", "filler", "reject")))
      paste(as.integer(tab), collapse = " / ")
    })
    output$preview <- DT::renderDT(dt_table(utils::head(prepared()$data, 200)))

    output$template <- downloadHandler(
      filename = function() "r4lineups_template.csv",
      content = function(file) utils::write.csv(trial_template(), file, row.names = FALSE)
    )

    reactive(list(
      data = prepared()$data,
      label = if (identical(input$source, "upload")) input$file$name else input$source,
      lineup_size = input$lineup_size,
      innocent_suspect = input$innocent_suspect %||% "auto",
      bins = parse_bins(input$bins),
      groups = groups(),
      has_rt = "response_time" %in% names(prepared()$data)
    ))
  })
}

# A one-line reminder, shown on each analysis tab, of which data it uses.
data_banner <- function(d) {
  g <- if (is.null(d$groups)) "" else
    sprintf(" · comparing %s: %s vs %s", d$groups$column, d$groups$labels[1], d$groups$labels[2])
  div(
    class = "small text-muted mb-2",
    icon("database"),
    sprintf(" Data: %s (%d rows) · lineup size %d%s. Change on the Data tab.",
            d$label, nrow(d$data), as.integer(d$lineup_size), g)
  )
}

# Says, when two groups are being compared, which results pool them.
group_scope_note <- function(d, text) {
  if (is.null(d$groups)) {
    return(NULL)
  }
  div(class = "small text-muted mb-2", icon("circle-info"),
      sprintf(" Comparing %s %s and %s. %s", d$groups$column, d$groups$labels[1],
              d$groups$labels[2], text))
}

# Face similarity with deepface embeddings. Local only: needs Python.

face_ui <- function(id) {
  ns <- NS(id)
  bslib::layout_sidebar(
    sidebar = bslib::sidebar(
      width = 330,
      fileInput(ns("target"), "Target (suspect) image", accept = c(".jpg", ".jpeg", ".png")),
      fileInput(ns("foils"), "Foil images", multiple = TRUE, accept = c(".jpg", ".jpeg", ".png")),
      selectInput(ns("model"), "Embedding model", choices = r4lineups::available_models(),
                  selected = "ArcFace"),
      selectInput(ns("detector"), "Face detector", choices = r4lineups::available_detectors(),
                  selected = "retinaface"),
      numericInput(ns("resize"), "Resize width before embedding (px, 0 = none)", 200, min = 0, step = 10),
      run_button(ns("run"), "Compute similarity"),
      actionButton(ns("run_matrix"), "Compute pairwise matrix", class = "w-100"),
      tags$hr(),
      bslib::accordion(
        open = FALSE,
        bslib::accordion_panel(
          "Python setup",
          helpText("Face similarity uses the Python package deepface through reticulate."),
          actionButton(ns("check"), "Check Python dependencies", class = "btn-sm w-100 mb-2"),
          bslib::input_switch(ns("confirm"), "I understand this installs Python packages"),
          actionButton(ns("install"), "Install Python dependencies", class = "btn-sm w-100")
        )
      )
    ),
    verbatimTextOutput(ns("status")),
    bslib::card(
      bslib::card_header("Lineup"),
      imageOutput(ns("lineup"), height = "auto")
    ),
    bslib::layout_columns(
      col_widths = c(6, 6),
      plot_card(ns, "sim_plot", "Similarity of each foil to the target"),
      table_card(ns, "sim_table", "Similarity table")
    ),
    table_card(ns, "matrix", "Pairwise similarity matrix")
  )
}

face_server <- function(id) {
  moduleServer(id, function(input, output, session) {
    status <- reactiveVal("Upload a target and at least one foil, then click 'Compute similarity'.")
    output$status <- renderText(status())

    observeEvent(input$check, {
      status(paste(utils::capture.output(
        tryCatch(r4lineups::check_python_deps(verbose = TRUE),
                 error = function(e) cat("Check failed:", conditionMessage(e)))
      ), collapse = "\n"))
    })
    observeEvent(input$install, {
      if (!isTRUE(input$confirm)) {
        status("Turn on the confirmation switch before installing.")
        return()
      }
      status("Installing Python dependencies; this can take several minutes...")
      status(tryCatch({
        r4lineups::install_r4lineups_python()
        "Install complete. Click 'Check Python dependencies' to verify."
      }, error = function(e) paste("Install failed:", conditionMessage(e))))
    })

    paths <- reactive({
      req(input$target, input$foils)
      width <- input$resize
      foil_names <- tools::file_path_sans_ext(input$foils$name)
      prep <- function(path, name) {
        if (is.na(width) || width <= 0) return(path)
        out <- file.path(tempdir(), paste0("r4l_", name, "_", width, ".jpg"))
        img <- magick::image_scale(magick::image_read(path), paste0(width, "x"))
        magick::image_write(img, out, format = "jpg")
        out
      }
      list(target = prep(input$target$datapath, "target"),
           foils = unname(mapply(prep, input$foils$datapath, paste0("foil_", foil_names))),
           foil_names = foil_names)
    })

    similarity <- reactive({
      p <- paths()
      withProgress(message = "Extracting embeddings", value = 0.3, {
        capture_notes(r4lineups::lineup_similarity(p$target, p$foils, model = input$model,
                                                   detector = input$detector,
                                                   foil_names = p$foil_names))
      })
    }) |>
      bindEvent(input$run)

    pairwise <- reactive({
      p <- paths()
      withProgress(message = "Computing pairwise similarities", value = 0.3, {
        m <- capture_notes(r4lineups::lineup_pairwise_matrix(p$target, p$foils, model = input$model,
                                                             detector = input$detector))$value
        as.data.frame(m)
      })
    }) |>
      bindEvent(input$run_matrix)

    output$lineup <- renderImage({
      p <- paths()
      img <- r4lineups::display_lineup(p$target, p$foils, ncol = 4, scale = 140)
      out <- tempfile(fileext = ".png")
      magick::image_write(img, out, format = "png")
